CREATE COLUMN TABLE "TEST_AP"."OMIV" ("Entry" INTEGER CS_INT NOT NULL , "Number" INTEGER CS_INT NOT NULL , "Date" LONGDATE CS_LONGDATE, "BPCode" NVARCHAR(15), "BPName" NVARCHAR(100), "Currency" NVARCHAR(3), "LastBilled" DECIMAL(21,6) CS_FIXED, "Paid" DECIMAL(21,6) CS_FIXED, "CarryForw" DECIMAL(21,6) CS_FIXED, "CurAmount" DECIMAL(21,6) CS_FIXED, "BillAmount" DECIMAL(21,6) CS_FIXED, "OBPaid" DECIMAL(21,6) CS_FIXED, "OBLstJENum" INTEGER CS_INT, "Predeces" INTEGER CS_INT, "Successor" INTEGER CS_INT, "Series" INTEGER CS_INT, "Cancelled" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("Entry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OMIV_Number" ON "TEST_AP"."OMIV" ( "Number" ASC )